def solve_problem(s, t):
    def lcp(a, b):
        n = max(len(a), len(b))
        for i in range(n):
            if a[i] != b[i]:
                return i
        return n

    def suffix_automaton(s):
        n = len(s)
        transitions = [[-1] * 26 for _ in range(n)]
        last = 0
        cnt = 0
        for i in range(n):
            cur = last
            while cur != -1 and s[cur] != s[i]:
                cur = transitions[cur][ord(s[i]) - ord('a')]
            if cur == -1:
                cnt += 1
                transitions[last][ord(s[i]) - ord('a')] = cnt - 1
                cur = cnt - 1
            else:
                cnt += 1
                transitions[cur][ord(s[i]) - ord('a')] = cnt - 1
                while last != cur and transitions[last][ord(s[i]) - ord('a')] != cnt - 1:
                    transitions[last][ord(s[i]) - ord('a')] = cnt - 1
                    last = transitions[last][ord(s[i]) - ord('a')]
            last = cnt - 1
        return transitions

    def suffix_array(s):
        n = len(s)
        sorted_pos = [0] * n
        for i in range(n):
            sorted_pos[i] = i
        sorted_pos.sort(key=lambda x: s[x])
        nxt = [-1] * n
        cnt = 1
        for i in range(1, n):
            if s[sorted_pos[i]] == s[sorted_pos[i - 1]]:
                nxt[sorted_pos[i]] = nxt[sorted_pos[i - 1]]
            else:
                nxt[sorted_pos[i]] = cnt
                cnt += 1
        pos = [[0] * (cnt + 1) for _ in range(n)]
        for i in range(1, n):
            pos[nxt[sorted_pos[i]]][i] = 1
        for i in range(cnt, 0, -1):
            for j in range(n):
                pos[i - 1][j] += pos[i][j]
        for i in range(n - 1, -1, -1):
            for j in range(n):
                sorted_pos[i] = pos[nxt[sorted_pos[i]]][j] + sorted_pos[i]
        sorted_pos.sort(key=lambda x: s[x])
        return sorted_pos

    if t < s:
        return "need tree"
    if lcp(s, t) == len(s) - len(t):
        return "array"
    if s == t:
        return "array"
    if len(s) - len(t) == 1 and s[-1] == t[-1]:
        return "automaton"
    return "both"

