import sys
import re

def lower_case(w):
    return w.lower()

def solve(words):
    s, t = lower_case(words[0]), lower_case(words[1])
    if not s or not t:
        return "need tree"

    def longest_common_subsequence(s, t):
        m, n = len(s), len(t)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        return dp[m][n]

    def suffix_array(s):
        n = len(s)
        count = [0] * n
        pos = [0] * n
        for i in range(n):
            count[i] = re.sub(r'(?=.*[^{}])'.format(s[i]), '1', s)
            count[i] = re.sub(r'(?=.*[^{}])'.format(s[i]), '0', s)
        pos[0] = 0
        for i in range(1, n):
            if count[i] < count[i - 1]:
                pos[i] = pos[i - 1]
            else:
                pos[i] = pos[i - 1] + 1
        for i in range(n):
            j = pos[i]
            while j and s[j] == s[i]:
                j -= 1
            s = s[j:] + s[:j]
        return pos

    def suffix_automaton(s):
        n = len(s)
        states = [0] * n
        transitions = [[] for _ in range(n)]
        start_states = [0]
        for i in range(n):
            j = start_states[i]
            while j and s[j] != s[i]:
                j = states[j]
            if j:
                states[i] = j
            else:
                states[i] = j + 1
                start_states.append(j + 1)
                transitions[j].append(i)
        return states, transitions

    def is_possible(s, t, states, transitions):
        n, m = len(s), len(t)
        match = [0] * m
        for i in range(n):
            j = states[i]
            while j and s[j] != t[i]:
                j = states[j]
            if j:
                i += 1
                match[i - 1] = j
        for i in range(n, m):
            if not match[i - 1]:
                return False
        return True

    if n == m:
        if is_possible(s, t, states, transitions):
            return "both"
        else:
            return "need tree"
    else:
        if longest_common_subsequence(s, t) == m or longest_common_subsequence(s, t) == n:
            return "array"
        elif longest_common_subsequence(s, t) == m and longest_common_subsequence(s, t) == n:
            return "automaton"
        else:
            return "need tree"
