    extended_string = s + s[:k]

    # Function to find the longest repeated substring of a given length
    def longest_repeated_substring(length):
        n = len(extended_string)
        dp = [[0] * n for _ in range(n)]
        max_length = 0
        for i in range(n):
            dp[i][i] = 1
        for length in range(2, length + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if extended_string[i] == extended_string[j] and dp[i + 1][j - 1] > 0:
                    dp[i][j] = dp[i + 1][j - 1] + 1
                    if dp[i][j] > max_length:
                        max_length = dp[i][j]
        return max_length

    # Find the longest repeated substring starting from 'a' to 'z'
    for char in 'abcdefghijklmnopqrstuvwxyz':
        substring = extended_string.find(char * 2)
        if substring != -1:
